class Let(object):
    """Let is a specifier type that binds values to names in the scope
    for use within a subspec.

    Args:
       spec: The subspec to evaluate with the bindings in scope
       **bindings: keyword arguments mapping names to specs/values
    """
    def __init__(self, spec, **bindings):
        self.spec = spec
        self.bindings = bindings

    def glomit(self, target, scope):
        new_scope = dict(scope)
        for name, subspec in self.bindings.items():
            new_scope[name] = scope[glom](target, subspec, scope)
        return scope[glom](target, self.spec, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %s)' % (cn, self.spec, ', '.join('%s=%r' % (k, v) for k, v in self.bindings.items()))
